#include "knapsack.h"

#include <algorithm>

namespace knapsack
{

int maximum_value(int max_weight, const std::vector<Item>& items)
{
    // dp[w] holds the greatest value achievable using at most weight w.
    std::vector<int> dp(max_weight + 1, 0);

    for (const Item& item : items)
    {
        // Iterate weights backwards so each item is used at most once.
        for (int w = max_weight; w >= item.weight; --w)
        {
            dp[w] = std::max(dp[w], dp[w - item.weight] + item.value);
        }
    }

    return dp[max_weight];
}

} // namespace knapsack

#include "knapsack.h"
#include <cassert>
#include <iostream>
#include <vector>

int main()
{
    using Item = knapsack::Item;
    int failures = 0;

    auto check = [&](const char* name, int got, int expected) {
        if (got == expected) {
            std::cout << "PASS: " << name << "\n";
        } else {
            std::cout << "FAIL: " << name << " (got " << got << ", expected " << expected << ")\n";
            ++failures;
        }
    };

    // no items
    check("no items", knapsack::maximum_value(100, {}), 0);

    // one item, too heavy
    check("one item, too heavy", knapsack::maximum_value(10, {{100, 1}}), 0);

    // five items (cannot be greedy by weight)
    check("five items (cannot be greedy by weight)",
          knapsack::maximum_value(10, {{2, 5}, {2, 5}, {2, 5}, {2, 5}, {10, 21}}), 21);

    // five items (cannot be greedy by value)
    check("five items (cannot be greedy by value)",
          knapsack::maximum_value(10, {{2, 20}, {2, 20}, {2, 20}, {2, 20}, {10, 50}}), 80);

    // example knapsack
    check("example knapsack",
          knapsack::maximum_value(10, {{5, 10}, {4, 40}, {6, 30}, {4, 50}}), 90);

    // 8 items
    check("8 items",
          knapsack::maximum_value(104, {{25, 350}, {35, 400}, {45, 450}, {5, 20},
                                        {25, 70}, {3, 8}, {2, 5}, {2, 5}}), 900);

    // 15 items
    check("15 items",
          knapsack::maximum_value(750, {{70, 135}, {73, 139}, {77, 149}, {80, 150},
                                        {82, 156}, {87, 163}, {90, 173}, {94, 184},
                                        {98, 192}, {106, 201}, {110, 210}, {113, 214},
                                        {115, 221}, {118, 229}, {120, 240}}), 1458);

    std::cout << (failures == 0 ? "ALL TESTS PASSED\n" : "SOME TESTS FAILED\n");
    return failures == 0 ? 0 : 1;
}

